#!/bin/bash
set -euo pipefail

LOG_FILE="/var/log/deploy.log"

log() { echo "[$(date +'%Y-%m-%d %H:%M:%S')] $1" | tee -a "$LOG_FILE"; }

check_deps() {
    local deps=("git" "node" "npm")
    for dep in "${deps[@]}"; do
        command -v "$dep" &>/dev/null || { log "ERROR: $dep not found"; exit 1; }
    done
    log "All dependencies found"
}

deploy() {
    log "Starting deployment..."
    git pull origin main
    npm ci --production
    pm2 restart app
    log "Deployment complete"
}

check_deps && deploy

#!/bin/bash

THRESHOLD=80
ALERT_EMAIL="admin@example.com"

check_disk() {
    df -h | awk 'NR>1 {gsub(/%/,"", $5); if($5 > '"$THRESHOLD"') print $1, $5"%", $6}'
}

check_memory() {
    free | awk '/Mem:/ {printf "Memory: %.1f%% used\n", $3/$2*100}'
}

check_cpu() {
    top -bn1 | grep 'Cpu(s)' | awk '{printf "CPU: %.1f%% used\n", 100-$8}'
}

echo "=== System Health Report ===$(date) ==="
check_disk
check_memory
check_cpu
